1583	+])('offsetMinutes(%s, %s) is %i', (tz, at, minutes) => {
1584	+  expect(offsetMinutes(new Date(at), tz)).toBe(minutes);
1585	+});
1586	+
1587	+test.each([
1588	+  ['2026-10-27', '20:30', 'Asia/Kolkata', '2026-10-27T15:00:00.000Z'],
1589	+  ['2026-03-08', '02:00', 'America/New_York', '2026-03-08T07:00:00.000Z'], // gap: 2:00 becomes 3:00 EDT
1590	+  ['2026-03-08', '02:30', 'America/New_York', '2026-03-08T07:30:00.000Z'], // gap: 2:30 becomes 3:30 EDT
1591	+  ['2026-03-29', '01:30', 'Europe/London', '2026-03-29T01:30:00.000Z'],    // gap: 1:30 becomes 2:30 BST
1592	+  ['2026-11-01', '01:30', 'America/New_York', '2026-11-01T05:30:00.000Z'], // repeated hour: first (EDT)
1593	+  ['2026-10-25', '01:30', 'Europe/London', '2026-10-25T00:30:00.000Z'],    // repeated hour: first (BST)
1594	+])('zonedTimeToInstant(%s %s, %s) is %s', (date, time, tz, expected) => {
1595	+  expect(zonedTimeToInstant(date, time, tz).toISOString()).toBe(expected);
