1620	@@ -0,0 +1,77 @@
1621	+// ponytail: Intl only; swap for Temporal.ZonedDateTime once Node and Safari ship it
1622	+
1623	+const formatters = new Map<string, Intl.DateTimeFormat>();
1624	+
1625	+// Slot building calls these hundreds of times per request, so formatters are built once per locale, zone and options.
1626	+function formatter(locale: string, timeZone: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
1627	+  const key = `${locale}|${timeZone}|${JSON.stringify(options)}`;
1628	+  let f = formatters.get(key);
1629	+  if (!f) {
1630	+    f = new Intl.DateTimeFormat(locale, { ...options, timeZone });
1631	+    formatters.set(key, f);
1632	+  }
1633	+  return f;
1634	+}
1635	+
1636	+// ICU accepts "IST" and maps it to India, so a zone without a "/" is only valid as "UTC" (spec §7 rule 8).
1637	+export function isValidTimeZone(tz: string): boolean {
1638	+  if (tz !== 'UTC' && !tz.includes('/')) return false;
1639	+  try {
1640	+    formatter('en-US', tz, {});
1641	+    return true;
1642	+  } catch {
1643	+    return false;
1644	+  }
1645	+}
1646	+
1647	+/** UTC offset of `tz` at the instant `at`, in minutes (-240, 330). */
1648	+export function offsetMinutes(at: Date, tz: string): number {
1649	+  const name = formatter('en-US', tz, { timeZoneName: 'longOffset' })
1650	+    .formatToParts(at)
1651	+    .find((p) => p.type === 'timeZoneName')?.value;
1652	+  if (name === 'GMT') return 0;
1653	+  const m = name?.match(/^GMT([+\-−])(\d\d):(\d\d)$/);
1654	+  if (!m) throw new Error(`cannot read the UTC offset of ${tz}: ${name}`);
1655	+  return (m[1] === '+' ? 1 : -1) * (Number(m[2]) * 60 + Number(m[3]));
1656	+}
1657	+
1658	+/** The calendar date at `at` in `tz`, as 'YYYY-MM-DD'. */
1659	+export function localDate(at: Date, tz: string): string {
1660	+  const parts = formatter('en-US', tz, { year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(at);
1661	+  const part = (type: string) => parts.find((p) => p.type === type)?.value;
1662	+  return `${part('year')}-${part('month')}-${part('day')}`;
1663	+}
1664	+
1665	+function parseDate(date: string): [number, number, number] {
1666	+  const [y, m, d] = date.split('-').map(Number);
1667	+  return [y!, m!, d!];
1668	+}
1669	+
1670	+/** Day of the week of a calendar date, 0 = Sunday. */
1671	+export function weekdayOf(date: string): number {
1672	+  const [y, m, d] = parseDate(date);
1673	+  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
1674	+}
1675	+
1676	+export function addDays(date: string, days: number): string {
1677	+  const [y, m, d] = parseDate(date);
1678	+  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
1679	+}
1680	+
1681	+/**
1682	+ * The instant at which `tz` reads `date` `time` ('HH:MM' or 'HH:MM:SS').
1683	+ * Matches Temporal's 'compatible' rule: a repeated hour resolves to its first pass,
1684	+ * and a time skipped by a clock change moves forward by the gap.
1685	+ */
1686	+export function zonedTimeToInstant(date: string, time: string, tz: string): Date {
1687	+  const [y, m, d] = parseDate(date);
1688	+  const [hh, mm, ss = 0] = time.split(':').map(Number);
1689	+  const wall = Date.UTC(y, m - 1, d, hh!, mm!, ss); // the wall-clock reading as if it were UTC
1690	+  const early = offsetMinutes(new Date(wall - 86_400_000), tz);
1691	+  const late = offsetMinutes(new Date(wall + 86_400_000), tz);
1692	+  const valid = [early, late]
1693	+    .map((o) => wall - o * 60_000)
1694	+    .filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
1695	+  // repeated hour: two valid instants, take the earlier; gap: none valid, move forward by the gap
1696	+  return new Date(valid.length ? Math.min(...valid) : wall - early * 60_000);
1697	+}
