// does ICU accept case variants of a zone name, and what does one cached formatter cost?
const variants = ['asia/kolkata','ASIA/KOLKATA','Asia/kolkata','aSIA/kOLKATA'];
for (const v of variants) {
  try { const f = new Intl.DateTimeFormat('en-US',{timeZone:v}); console.log(JSON.stringify(v),'ok ->',f.resolvedOptions().timeZone); }
  catch(e){ console.log(JSON.stringify(v),'throws'); }
}
// distinct valid spellings of one 11-letter zone
const base='Asia/Kolkata', n=base.replace(/[^a-z]/gi,'').length;
console.log('letters',n,'case variants',2**n);
// memory per cached formatter
if (global.gc) global.gc();
const before=process.memoryUsage().heapUsed;
const m=new Map(); const N=2000;
for(let i=0;i<N;i++){ let s=''; for(let j=0;j<base.length;j++){ const c=base[j]; s+= (i>>(j%11))&1 ? c.toUpperCase():c.toLowerCase(); } s+=''; const key=s+'|'+i; m.set(key,new Intl.DateTimeFormat('en-US',{timeZone:s})); }
if (global.gc) global.gc();
console.log('approx KB per formatter',((process.memoryUsage().heapUsed-before)/N/1024).toFixed(1),'(distinct map keys',m.size,')');
// other slash-bearing names ICU accepts that are not zones?
for (const v of ['Etc/GMT+5','America/Argentina/ComodRivadavia','+05:30','Asia/Kolkata ','Asia/Kolkata/','/','a/b']) {
  try { new Intl.DateTimeFormat('en-US',{timeZone:v}); console.log(JSON.stringify(v),'ACCEPTED'); } catch { console.log(JSON.stringify(v),'rejected'); }
}
EOF
node --expose-gc cachecheck.mjs

